-- Client table SkillGemInfo: all 204 rows of the 3.29.3c client. Written by scripts/dev/client-sql.ps1.
INSERT INTO "SkillGemInfo" ("_row", "Id", "Description", "VideoURL1", "SkillGemsKey", "VideoURL2", "CharactersKeys") VALUES
(0, 'Blight&ArcaneSurge', 'Grants a temporary buff after spending enough mana with Blight. The buff grants Blight more spell damage, and mana regeneration for sustaining casting.', 'http://web.poecdn.com/public/videos/Blight/Blight+Arcane%20Surge.bk2 ', 342, 'http://down.qq.com/poe/videos/skills/Blight/Blight+ArcaneSurge.bk2', '[1,6,2,5]'),
(1, 'Blight&ControlledDestruction', 'Grants more spell damage but reduces critical strike chance. However, Blight cannot critically hit meaning Controlled Destruction gives more spell damage with no drawbacks.', 'http://web.poecdn.com/public/videos/Blight/Blight+Controlled%20Destruction.bk2 ', 310, 'http://down.qq.com/poe/videos/skills/Blight/Blight+ControlledDestruction.bk2', '[]'),
(2, 'Blight&Efficacy', 'Increases the damage over time and spell damage of Blight. The increased skill effect duration also increases the duration of Blight''s debuff on enemies.', 'http://web.poecdn.com/public/videos/Blight/Blight+Efficacy.bk2 ', 334, 'http://down.qq.com/poe/videos/skills/Blight/Blight+Efficacy.bk2', '[]'),
(3, 'Blight&SwiftAffliction', 'Decreases the total duration of Blight''s debuff effect but compensates for this by increasing damage over time dealt by Blight.', 'http://web.poecdn.com/public/videos/Blight/Blight+SwiftAffliction.bk2 ', 311, 'http://down.qq.com/poe/videos/skills/Blight/Blight+SwiftAffliction.bk2', '[]'),
(4, 'Blight&IncreasedAreaOfEffect', 'Increases the area of effect of Blight allowing it to affect a greater number of targets at once.', 'http://web.poecdn.com/public/videos/Blight/Blight+IncreasedArea%20of%20Effect.bk2', 39, 'http://down.qq.com/poe/videos/skills/Blight/Blight+IncreasedArea.bk2', '[]'),
(5, 'FreezingPulse&LMP', 'Increases the amount of projectiles Freezing Pulse casts, allowing it to hit more targets at once.

At later levels, obtain the Greater Multiple Projectiles Support gem to hit enemies in a larger area.', 'http://web.poecdn.com/public/videos/FreezingPulse/FreezingPulse+LesserMultipleProjectiles.bk2 ', 35, 'http://down.qq.com/poe/videos/skills/FreezingPulse/FreezingPulse+LMP.bk2', '[2,4,5,3,1]'),
(6, 'FreezingPulse&ColdPenetration', 'Reduces enemy resistance to cold damage, making them take more cold damage from Freezing Pulse.', 'http://web.poecdn.com/public/videos/FreezingPulse/FreezingPulse+ColdPenetration.bk2 ', 175, 'http://down.qq.com/poe/videos/skills/FreezingPulse/FreezingPulse+ColdPenetration.bk2', '[]'),
(7, 'FreezingPulse&ControlledDestruction', 'Grants more spell damage to Freezing Pulse but reduces critical strike chance. The more spell damage provided by this support allows a direct and stable increase in damage not contingent on critical strikes.', 'http://web.poecdn.com/public/videos/FreezingPulse/FreezingPulse+ControlledDestruction.bk2 ', 310, 'http://down.qq.com/poe/videos/skills/FreezingPulse/FreezingPulse+ControlledDestruction.bk2', '[]'),
(8, 'FreezingPulse&FasterProjectiles', 'Increases Freezing Pulse''s projectile speed, increasing the maximum distance that the projectiles travel. This allows Freezing Pulse to hit targets further away.', 'http://web.poecdn.com/public/videos/FreezingPulse/FreezingPulse+FasterProjectiles.bk2 ', 36, 'http://down.qq.com/poe/videos/skills/FreezingPulse/FreezingPulse+FasterProjectiles.bk2', '[]'),
(9, 'FreezingPulse&SpellEcho', 'Repeats Freezing Pulse an additional time while also greatly increasing the cast speed.', 'http://web.poecdn.com/public/videos/FreezingPulse/FreezingPulse+SpellEcho.bk2 ', 190, 'http://down.qq.com/poe/videos/skills/FreezingPulse/FreezingPulse+SpellEcho.bk2', '[]'),
(10, 'FreezingPulse&Volley', 'Increases the number of projectiles Freezing Pulse casts. Projectiles are in parallel to each other allowing a greater number of targets to be hit at once.', 'http://web.poecdn.com/public/videos/FreezingPulse/FreezingPulse+Volley.bk2 ', 349, 'http://down.qq.com/poe/videos/skills/FreezingPulse/FreezingPulse+Volley.bk2', '[2,4,0,1,5,3]'),
(11, 'LightingTendrils&AddedLightningDamage', 'Increases the amount of flat lightning damage your Lightning Tendrils does.', 'http://web.poecdn.com/public/videos/LightningTendrils/Lighting%20Tendrils+AddedLightningDamage.bk2', 40, 'http://down.qq.com/poe/videos/skills/LightningTendrils/LightningTendrils+AddedLightningDamage.bk2', '[6,2,1,5]'),
(12, 'LightingTendrils&ControlledDestruction', 'Grants more spell damage to Lightning Tendrils but reduces critical strike chance. The more spell damage provided by this support allows a direct and stable increase in damage, not contingent on critical strikes.', 'http://web.poecdn.com/public/videos/LightningTendrils/LightningTendrils+ControlledDestruction.bk2 ', 310, 'http://down.qq.com/poe/videos/skills/LightningTendrils/LightningTendrils+ControlledDestruction.bk2', '[]'),
(13, 'LightingTendrils&ElementalFocus', 'Removes the ability for Lightning Tendrils to inflict elemental ailments, such as shock, on enemies. However, it significantly boosts Lightning Tendril''s elemental damage.', 'http://web.poecdn.com/public/videos/LightningTendrils/LightningTendrils+ElementalFocus_1.bk2 ', 319, 'http://down.qq.com/poe/videos/skills/LightningTendrils/LightingTendrils+ElementalFocus.bk2', '[]'),
(14, 'LightingTendrils&LightningPenetration', 'Reduces enemy resistance to lightning damage, making them take more lightning damage from Lightning Tendrils.', 'http://web.poecdn.com/public/videos/LightningTendrils/LightningTendrils+ElementalFocus_1.bk2 ', 176, 'http://down.qq.com/poe/videos/skills/LightningTendrils/LightningTendrils+LightningPenetration.bk2', '[]'),
(15, 'MagmaOrb&Combustion', 'Gives Rolling Magma more fire damage, additional chance to ignite enemies and reduces the fire resistance of ignited enemies. This makes it a great all-round support for any fire based skill.', 'http://web.poecdn.com/public/videos/MagmaOrb/MagmaOrb+Combustion.bk2', 110, 'http://down.qq.com/poe/videos/skills/MagmaOrb/MagmaOrb+Combustion.bk2', '[6,0,1,5]'),
(16, 'MagmaOrb&LMP', 'Increases the amount of projectiles Rolling Magma casts, allowing it to hit more targets at once.

At later levels, obtain the Greater Multiple Projectiles Support gem to hit enemies in a larger area.', 'http://web.poecdn.com/public/videos/MagmaOrb/MagmaOrb+LesserMultipleProjections.bk2 ', 35, 'http://down.qq.com/poe/videos/skills/MagmaOrb/MagmaOrb+LMP.bk2', '[2,4,5,3,1]'),
(17, 'MagmaOrb&FirePenetration', 'Reduces enemy resistance to fire damage, making them take more fire damage from Rolling Magma.', 'http://web.poecdn.com/public/videos/MagmaOrb/MagmaOrb+FirePenetration.bk2 ', 174, 'http://down.qq.com/poe/videos/skills/MagmaOrb/MagmaOrb+FirePenetration.bk2', '[]'),
(18, 'MagmaOrb&SpellEcho', 'Repeats Rolling Magma an additional time while also greatly increasing the cast speed.', 'http://web.poecdn.com/public/videos/MagmaOrb/MagmaOrb+SpellEcho.bk2 ', 190, 'http://down.qq.com/poe/videos/skills/MagmaOrb/MagmaOrb+SpellEcho.bk2', '[]'),
(19, 'MagmaOrb&SlowerProjectiles', 'Increases Rolling Magma''s damage and decreases the distance between each chain, allowing one orb to impact on a pack of monsters multiple times.', 'http://web.poecdn.com/public/videos/MagmaOrb/MagmaOrb+SlowerProjectiles.bk2 ', 211, 'http://down.qq.com/poe/videos/skills/MagmaOrb/MagmaOrb+SlowerProjectiles.bk2', '[]'),
(20, 'MagmaOrb&Empower', 'Raises the gem level of Rolling Magma granting additional base fire damage and potentially allowing it to chain additional times. This is a drop-only gem that is very rare. Levelling this support gem takes a long time making it not very useful early on.', 'http://web.poecdn.com/public/videos/MagmaOrb/MagmaOrb+Empower.bk2 ', 202, 'http://down.qq.com/poe/videos/skills/MagmaOrb/MagmaOrb+Empower.bk2', '[]'),
(21, 'Fireball&BurningDamage', 'Greatly increases the damage over time dealt by ignites inflicted from Fireball. ', 'http://web.poecdn.com/public/videos/Fireball/Fireball+BurningDamage.bk2', 194, 'http://down.qq.com/poe/videos/skills/Fireball/Fireball+BurningDamage.bk2', '[]'),
(22, 'Fireball&Combustion', 'Gives Fireball more fire damage, additional chance to ignite enemies and reduces the fire resistance of ignited enemies. This makes it a great all-round support for any fire based skill.', 'http://web.poecdn.com/public/videos/Fireball/Fireball+Combustion.bk2', 110, 'http://down.qq.com/poe/videos/skills/Fireball/Fireball+Combustion.bk2', '[6,0,1,5]'),
(23, 'Fireball&ControlledDestruction', 'Grants more spell damage to Fireball but reduces critical strike chance. The more spell damage provided by this support allows a direct and stable increase in damage not contingent on critical strikes.', 'http://web.poecdn.com/public/videos/Fireball/Fireball+ControlledDestruction.bk2', 310, 'http://down.qq.com/poe/videos/skills/Fireball/Fireball+ControlledDestruction.bk2', '[]'),
(24, 'Fireball&DeadlyAilments', 'Reduces the hit damage of Fireball in exchange for more ailment damage. This makes it particularly strong for Fireball characters that want to focus on scaling the damage over time of ignites.', 'http://web.poecdn.com/public/videos/Fireball/Fireball+DeadlyAilments.bk2', 331, 'http://down.qq.com/poe/videos/skills/Fireball/Fireball+DeadlyAilments.bk2', '[]'),
(25, 'Fireball&FirePenetration', 'Reduces enemy resistance to fire damage, making them take more fire damage from Fireball.', 'http://web.poecdn.com/public/videos/Fireball/Fireball+FirePenetration.bk2', 174, 'http://down.qq.com/poe/videos/skills/Fireball/Fireball+FirePenetration.bk2', '[]'),
(26, 'Fireball&IgniteProliferate', 'Increases the chance to inflict ignites on enemies with Fireball, whilst also enabling ignites to spread to nearby enemies.', 'http://web.poecdn.com/public/videos/Fireball/Fireball+IgniteProliferation.bk2', 328, 'http://down.qq.com/poe/videos/skills/Fireball/Fireball+IgniteProliferation.bk2', '[]'),
(27, 'Fireball&LMP', 'Increases the amount of projectiles Fireball casts, allowing it to hit more targets at once.

At later levels, obtain the Greater Multiple Projectiles Support gem to hit enemies in a larger area.', 'http://web.poecdn.com/public/videos/Fireball/Fireball+LesserMultipleProjectiles.bk2', 35, 'http://down.qq.com/poe/videos/skills/Fireball/Fireball+LMP.bk2', '[2,4,5,3,1]'),
(28, 'Fireball&SpellEcho', 'Repeats Fireball an additional time while also greatly increasing the cast speed.', 'http://web.poecdn.com/public/videos/Fireball/Fireball+SpellEcho.bk2', 190, 'http://down.qq.com/poe/videos/skills/Fireball/Fireball+SpellEcho.bk2', '[]'),
(29, 'Fireball&SwiftAffliction', 'Decreases the total duration of ignites on enemies but increases the damage that ignites deal, allowing your ignites to burn faster and stronger.', 'http://web.poecdn.com/public/videos/Fireball/Fireball+SwiftAffliction.bk2', 311, 'http://down.qq.com/poe/videos/skills/Fireball/Fireball+SwiftAffliction.bk2', '[]'),
(30, 'RaiseZombie&FasterAttacks', 'Increases the attack speed of your zombie minions.', 'http://web.poecdn.com/public/videos/RaiseZombies/RaiseZombies+FasterAttacks.bk2', 33, 'http://down.qq.com/poe/videos/skills/RaiseZombies/RaiseZombies+FasterAttacks.bk2', '[]'),
(31, 'RaiseZombie&MeleeSplash', 'Turns the basic attack of your zombie minions into an area of effect attack. This means that multiple enemies can be hit simultaneously by their basic attack. ', 'http://web.poecdn.com/public/videos/RaiseZombies/RaiseZombies+MeleeSplash.bk2', 191, 'http://down.qq.com/poe/videos/skills/RaiseZombies/RaiseZombies+MeleeSplash.bk2', '[6,2,4,0,1,5,3]'),
(32, 'RaiseZombie&MinionDamage', 'Provides more damage to your zombie minions.', 'http://web.poecdn.com/public/videos/RaiseZombies/RaiseZombies+MinionDamage.bk2', 107, 'http://down.qq.com/poe/videos/skills/RaiseZombies/RaiseZombies+MinionDamage.bk2', '[6,2,4]'),
(33, 'RaiseZombie&MinionHealth', 'Increases the maximum life of your zombie minions, allowing them to survive longer against hard hitting enemies.', 'http://web.poecdn.com/public/videos/RaiseZombies/RaiseZombies+MinionHealth.bk2', 112, 'http://down.qq.com/poe/videos/skills/RaiseZombies/RaiseZombies+MinionLife.bk2', '[]'),
(34, 'RaiseZombie&Multistrike', 'Causes your zombie minion''s powerful ground slam area of effect skill to repeat an additional two times.', 'http://web.poecdn.com/public/videos/RaiseZombies/RaiseZombies+Multistrike.bk2', 189, 'http://down.qq.com/poe/videos/skills/RaiseZombies/RaiseZombies+Multistrike.bk2', '[]'),
(35, 'RaiseZombie&MinionTotemResistance', 'Reduces the elemental damage that your zombies take, allowing them to survive longer against elemental, damage-dealing enemies.', 'http://web.poecdn.com/public/videos/RaiseZombies/RaiseZombies+TotemandElementalResist.bk2', 195, 'http://down.qq.com/poe/videos/skills/RaiseZombies/RaiseZombie+MinionResist.bk2', '[]'),
(36, 'GlacialHammer&AncestralCall', 'Allows Glacial Hammer to target two additional nearby enemies. Pairing this support with the Melee Splash support will result in large areas of overlapping damage. ', 'http://web.poecdn.com/public/videos/GlacialHammer/GlacialHammer+AncestralCall.bk2', 351, 'http://down.qq.com/poe/videos/skills/GlacialHammer/GlacialHammer+AncestralCall.bk2', '[6,2,4,0,3]'),
(37, 'GlacialHammer&IceBite', 'Adds flat cold damage to Glacial Hammer, an increased chance to freeze, chance to generate frenzy charges on killing frozen enemies and adds cold damage per frenzy charge on you. This synergises well with Glacial Hammer''s built in shatter against frozen enemies on low life.', 'http://web.poecdn.com/public/videos/GlacialHammer/GlacialHammer+Icebite.bk2', 283, 'http://down.qq.com/poe/videos/skills/GlacialHammer/GlacialHammer+IceBite.bk2', '[]'),
(38, 'GlacialHammer&MeleePhysical', 'Grants more melee physical damage for Glacial Hammer. Because 50% of physical damage is converted to cold damage, this support will also increase the cold damage done by Glacial Hammer. ', 'http://web.poecdn.com/public/videos/GlacialHammer/GlacialHammer+MeleePhysicalDamage.bk2', 83, 'http://down.qq.com/poe/videos/skills/GlacialHammer/GlacialHammer+MeleePhysicalDamage.bk2', '[]'),
(39, 'GlacialHammer&MeleeSplash', 'Allows your Glacial Hammer hits to deal splash damage to nearby targets. Pairing this support with the Ancestral Call support will result in large areas of overlapping damage.', 'http://web.poecdn.com/public/videos/GlacialHammer/GlacialHammer+MeleeSplash.bk2', 191, 'http://down.qq.com/poe/videos/skills/GlacialHammer/GlacialHammer+MeleeSplash.bk2', '[6,2,4,0,1,5,3]'),
(40, 'GlacialHammer&Multistrike', 'Causes Glacial Hammer to repeat an additional two times, as well as providing a large bonus to attack speed.', 'http://web.poecdn.com/public/videos/GlacialHammer/GlacialHammer+Multistrike.bk2', 189, 'http://down.qq.com/poe/videos/skills/GlacialHammer/GlacialHammer+Multistrike.bk2', '[]'),
(41, 'GlacialHammer&ColdPenetration', 'Cold Penetration reduces enemy resistance to cold damage, making them take more cold damage from Glacial Hammer.', 'http://web.poecdn.com/public/videos/GlacialHammer/GlacialHammer+ColdPenetration.bk2', 175, 'http://down.qq.com/poe/videos/skills/GlacialHammer/GlacialHammer+ColdPenetration.bk2', '[]'),
(42, 'EtheralKnives&ControlledDestruction', 'Grants more spell damage to Ethereal Knives but reduces critical strike chance. The more spell damage provided by this support allows a direct and stable increase in damage not contingent on critical strikes.', 'http://web.poecdn.com/public/videos/EtherealKnives/EtherealKnives+ControlledDestruction.bk2', 310, 'http://down.qq.com/poe/videos/skills/EtherealKnives/EtherealKnives+ControlledDestruction.bk2', '[]'),
(43, 'EtheralKnives&FasterCasting', 'Increases the cast speed of Ethereal Knives, allowing it to be used more frequently.', 'http://web.poecdn.com/public/videos/EtherealKnives/EtherealKnives+FasterCasting.bk2', 86, 'http://down.qq.com/poe/videos/skills/EtherealKnives/EtherealKnives+FasterCasting.bk2', '[]'),
(44, 'EtheralKnives&FasterProjectiles', 'Increasing the projectile speed of Ethereal Knives increases how far the projectiles can travel. When paired with the Pierce support, Faster Projectiles will allow your projectiles to travel deeply through packs of mobs.', 'http://web.poecdn.com/public/videos/EtherealKnives/EtherealKnives+FasterProjectiles.bk2', 36, 'http://down.qq.com/poe/videos/skills/EtherealKnives/EtherealKnives+FasterProjectiles.bk2', '[]'),
(45, 'EtheralKnives&PhysicalToLightning', 'Converts 50% of Ethereal Knives'' physical damage to lightning damage, as well as providing extra lightning damage based on your physical damage.', 'http://web.poecdn.com/public/videos/EtherealKnives/EtherealKnives+PhysicaltoLightning.bk2', 267, 'http://down.qq.com/poe/videos/skills/EtherealKnives/EtherealKnives+PhysicaltoLightning.bk2', '[]'),
(46, 'EtheralKnives&Pierce', 'Allows projectiles from Ethereal Knives to travel through extra numbers of enemies, ensuring that more enemies in a pack will be hit by the projectiles.', 'http://web.poecdn.com/public/videos/EtherealKnives/EtherealKnives+Pierce.bk2', 69, 'http://down.qq.com/poe/videos/skills/EtherealKnives/EtherealKnives+Pierce.bk2', '[3,2,4,5]'),
(47, 'EtheralKnives&SpellEcho', 'Repeats Ethereal Knives an additional time while also greatly increasing the cast speed.', 'http://web.poecdn.com/public/videos/EtherealKnives/EtherealKnives+SpellEcho.bk2', 190, 'http://down.qq.com/poe/videos/skills/EtherealKnives/EtherealKnives+SpellEcho.bk2', '[]'),
(48, 'ExplosiveTrap&TrapMineDamage', 'Grants more damage to your Explosive Trap. It also adds a small penalty to trap throwing speed.', 'http://web.poecdn.com/public/videos/ExplosiveTrap/ExplosireTrap+TrapandMineDamage.bk2', 287, 'http://down.qq.com/poe/videos/skills/ExplosiveTrap/ExplosiveTrap+TrapandMineDamage.bk2', '[]'),
(49, 'ExplosiveTrap&ClusterTraps', 'Allows you to throw 2 additional Explosive Traps at once.', 'http://web.poecdn.com/public/videos/ExplosiveTrap/ExplosiveTrap+ClusterTraps.bk2', 312, 'http://down.qq.com/poe/videos/skills/ExplosiveTrap/ExplosiveTrap+ClusterTrap.bk2', '[]'),
(50, 'ExplosiveTrap&ChargedTraps', 'Grants a chance to gain frenzy and power charges when your Explosive Trap is triggered by enemies. It also grants increased trap throwing speed per frenzy charge and increased critical strike multiplier per power charge. ', 'http://web.poecdn.com/public/videos/ExplosiveTrap/ExplosiveTrap+ChargedTraps.bk2', 364, 'http://down.qq.com/poe/videos/skills/ExplosiveTrap/ExplosiveTrap+ChargedTrap.bk2', '[]'),
(51, 'ExplosiveTrap&ControlledDestruction', 'Grants more spell damage to Explosive Trap but reduces critical strike chance. The more spell damage provided by this support allows a direct and stable increase in damage not contingent on critical strikes.', 'http://web.poecdn.com/public/videos/ExplosiveTrap/ExplosiveTrap+ControlledDestruction.bk2', 310, 'http://down.qq.com/poe/videos/skills/ExplosiveTrap/ExplosiveTrap+ControlledDestruction.bk2', '[]'),
(52, 'ExplosiveTrap&ElementalFocus', 'Removes the ability for Explosive Trap to inflict elemental ailments, such as ignite, on enemies. However, it significantly increases the amount of elemental damage Explosive Trap does. Converting all physical damage from Explosive Trap to elemental damage maximizes the benefit this support provides.', 'http://web.poecdn.com/public/videos/ExplosiveTrap/ExplosiveTrap+ElementalFocus.bk2', 319, 'http://down.qq.com/poe/videos/skills/ExplosiveTrap/ExplosiveTrap+ElementalFocus.bk2', '[]'),
(53, 'ExplosiveTrap&PhysicalToLightning', 'Converts 50% of Explosive Trap''s physical damage to lightning damage, as well as providing extra lightning damage based on your physical damage.', 'http://web.poecdn.com/public/videos/ExplosiveTrap/ExplosiveTrap+PhysicaltoLightning.bk2', 267, 'http://down.qq.com/poe/videos/skills/ExplosiveTrap/ExplosiveTrap+PhysicaltoLightning.bk2', '[]'),
(54, 'FrostBlades&AncestralCall', 'Allows Frost Blades to target two additional nearby enemies. With at least three enemies nearby this can result in triple the amount of blade projectiles.', 'http://web.poecdn.com/public/videos/FrostBlades/FrostBlades+AncestralCall.bk2', 351, 'http://down.qq.com/poe/videos/skills/FrostBlades/FrostBlades+AncestralCall.bk2', '[6,2,4,0,3]'),
(55, 'FrostBlades&ColdPenetration', 'Reduces enemy resistance to cold damage, making them take more cold damage from Frost Blades.', 'http://web.poecdn.com/public/videos/FrostBlades/FrostBlades+ColdPenetration.bk2', 175, 'http://down.qq.com/poe/videos/skills/FrostBlades/Frostblades+ColdPenetration.bk2', '[]'),
(56, 'FrostBlades&ElementalDamageWithAttacks', 'Multiplies the elemental damage done by Frost Blades. Converting all physical damage from Frost Blades to elemental damage maximizes the benefit this support provides.', 'http://web.poecdn.com/public/videos/FrostBlades/FrostBlades+ElementalDamagewithAttacks.bk2', 113, 'http://down.qq.com/poe/videos/skills/FrostBlades/FrostBlade+WeaponElementalDamage.bk2', '[]'),
(57, 'FrostBlades&MeleePhysical', 'Grants more melee physical damage for Frost Blades. Because 60% of physical damage is converted to cold damage, this support will also increase the cold damage done by Frost Blades.', 'http://web.poecdn.com/public/videos/FrostBlades/FrostBlades+MeleePhysicalDamage.bk2', 83, 'http://down.qq.com/poe/videos/skills/FrostBlades/Frostblades+MeleePhysicalDamage.bk2', '[]'),
(58, 'FrostBlades&Multistrike', 'Causes Frost Blades to repeat an additional two times, as well as providing a large bonus to attack speed.', 'http://web.poecdn.com/public/videos/FrostBlades/FrostBlades+Multistrike.bk2', 189, 'http://down.qq.com/poe/videos/skills/FrostBlades/Frostblades+Multistrike.bk2', '[]'),
(59, 'FrostBlades&SlowerProjectiles', 'Reduces the maximum range of Frost Blades projectiles, while also granting more damage with the blade projectiles.', 'http://web.poecdn.com/public/videos/FrostBlades/FrostBlades+SlowerProjectiles.bk2', 211, 'http://down.qq.com/poe/videos/skills/FrostBlades/Frostblades+SlowerProjectiles.bk2', '[]'),
(60, 'ViperStrike&MeleeSplash', 'Allows your Viper Strike hits to deal splash damage to nearby targets. Pairing this support with the Ancestral Call support will result in large areas of overlapping damage.', 'http://web.poecdn.com/public/videos/ViperStrike/ViperStrike+MeleeSplash.bk2', 191, 'http://down.qq.com/poe/videos/skills/ViperStrike/ViperStrike+MeleeSplash.bk2', '[6,2,4,0,1,5,3]'),
(61, 'ViperStrike&AncestralCall', 'Allows Viper Strike to target two additional nearby enemies. Pairing this support with the Melee Splash support will result in large areas of overlapping damage.', 'http://web.poecdn.com/public/videos/ViperStrike/ViperStrike+AncestralCall.bk2', 351, 'http://down.qq.com/poe/videos/skills/ViperStrike/ViperStrike+AncestralCall.bk2', '[6,2,4,0,3]'),
(62, 'ViperStrike&DeadlyAilments', 'Reduces hit damage in exchange for more ailment damage. This allows the poison inflicted by Viper Strike to deal far more damage over time.', 'http://web.poecdn.com/public/videos/ViperStrike/ViperStrike+DeadlyAilments.bk2', 331, 'http://down.qq.com/poe/videos/skills/ViperStrike/ViperStrike+DeadlyAilments.bk2', '[]'),
(63, 'ViperStrike&MeleePhysical', 'Grants more melee physical damage for Viper Strike. This support also increases the amount of damage inflicted bleeds and poisons do.', 'http://web.poecdn.com/public/videos/ViperStrike/ViperStrike+MeleePhysicalDamage.bk2', 83, 'http://down.qq.com/poe/videos/skills/ViperStrike/ViperStrike+MeleePhysicalDamage.bk2', '[]'),
(64, 'ViperStrike&Multistrike', 'Causes Viper Strike to repeat an additional two times, as well as providing a large bonus to attack speed.', 'http://web.poecdn.com/public/videos/ViperStrike/ViperStrike+Multistrike.bk2', 189, 'http://down.qq.com/poe/videos/skills/ViperStrike/ViperStrike+Multistrike.bk2', '[]'),
